55. 	tp := github.BasicAuthTransport{
56. 		Username: strings.TrimSpace(githubUsername),
57. 		Password: strings.TrimSpace(githubToken),
58. 	}
59. 	ghClient := github.NewClient(tp.Client())
60. 
