71. func (g GithubClient) Clone(cloneDir string) error {
72. 
73. 	repoURL := fmt.Sprintf("https://%s:%s@github.com/%s/%s.git", g.username, g.token, g.ownerName, g.repoName)
74. 	cloneCmd := exec.Command("git", "clone", repoURL, cloneDir)
75. 	// git clone the repo
76. 	log.Printf("git cloning into %q", cloneDir)
