83. func (g GithubClient) CreateAtlantisWebhook(ctx context.Context, hookURL string) (int64, error) {
84. 	contentType := "json"
85. 	hookConfig := &github.HookConfig{
86. 		ContentType: &contentType,
87. 		URL:         &hookURL,
88. 	}
89. 	// create atlantis hook
90. 	atlantisHook := &github.Hook{
91. 		Events: []string{"issue_comment", "pull_request", "push"},
92. 		Config: hookConfig,
93. 		Active: github.Bool(true),
94. 	}
95. 
